/bin/bash -lc "python - <<'PY'
import urllib.request, concurrent.futures
urls=['https://assemblyai.com/docs/pre-recorded-audio/select-the-language-to-transcribe','https://raw.githubusercontent.com/AssemblyAI/assemblyai-python-sdk/master/assemblyai/types.py','https://api.assemblyai.com/v2/transcript?limit=1']
def fetch(u):
 try:
  with urllib.request.urlopen(u, timeout=25) as r: s=r.read().decode()
  path='/tmp/aai-'+str(urls.index(u))+'.txt';open(path,'w').write(s);return u,path,len(s),s[:150]
 except Exception as e: return u,str(e)
for x in concurrent.futures.ThreadPoolExecutor().map(fetch,urls): print(x)
PY"

